const $=id=>document.getElementById(id),el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
document.documentElement.dataset.appReady='true';
const labels={overview:'总览',conversations:'聊天归档',memories:'长期记忆',profile:'个人画像',accounts:'社交账号',knowledge:'知识资料',daily:'每日归档',conflicts:'记忆冲突',clients:'客户端授权',security:'账号安全',search:'搜索结果'};
const subtitles={models:'配置检索与概要服务，密钥不会回显。',rag:'索引进度、模型用量与带证据的交接概要。',projects:'主线任务、近期目标与下一步。',overview:'让散落的数字信息，有一个共同的归处。',conversations:'跨平台保留原文，让每一次讨论都可以回溯。',memories:'留下重要事实、决定和偏好，保持更新的轨迹。',profile:'从明确的信息认识你，每一项都有来源。',accounts:'你的线上身份、创作方向和账号用途。',knowledge:'保存原文与出处，让过去的知识更容易被找到。',daily:'每天用了哪些 AI，聊过什么，完成了什么。',conflicts:'信息发生变化时，由你决定采用哪个版本。',clients:'按需授权，让不同 AI 共享同一份上下文。',security:'管理你的登录密码和双重验证。'};
labels.automatic='自动记忆';subtitles.automatic='查看客户端自动读取、归档与概要更新的实际状态。';labels.models='模型设置';labels.rag='检索与概要';labels.projects='主线与计划';
labels.strategy='战略目标';subtitles.strategy='由你维护并发布，Agent 只读的总战略、阶段战略和月目标。';labels.overviewdetail='个人总概览';subtitles.overviewdetail='详细个人信息、项目进度、主线任务与下一步，逐项保留原文出处。';labels.classified='记忆分类';subtitles.classified='按个人信息、开发项目和其他讨论查阅已提交资料。';let selectedCategory='personal';
const protectionLabels={public:'L0 公开',normal:'L1 普通',sensitive:'L2 私密',restricted:'L3 高敏感'};
const types={memory:'长期记忆',profile:'画像',event:'事件',context:'上下文',summary:'摘要',message:'消息',project:'主线项目',task:'近期计划'};
const platforms={chatgpt:'ChatGPT',codex:'Codex','codex-local':'Codex 本机','codex-cloud':'Codex 云端',antigravity:'Antigravity','claude-code':'Claude Code','memory-hub-archiver':'归档助手','memory-dashboard':'管理界面'};
const platform=p=>platforms[p]??p,date=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'暂无';
let issuedClientKey=null;
function clearIssuedClientKey(){if(issuedClientKey){issuedClientKey.token='';issuedClientKey.input.value='';issuedClientKey=null;}}
let session=null,active='overview',generation=0,imports=null;const pending=new Set();const channel=new BroadcastChannel('memory-hub-lock');
const can=scope=>session?.scopes.includes(scope);
function notice(text,bad=false){$('notice').textContent=text;$('notice').className=bad?'error':'';}
function lock(message=''){clearIssuedClientKey();generation++;for(const c of pending)c.abort();pending.clear();session=null;imports=null;$('workspace').hidden=true;$('login').hidden=false;$('content').replaceChildren();$('detail-body').replaceChildren();$('detail-title').textContent='记录详情';$('detail').close();$('import-dialog').close();$('import-preview').textContent='请选择文件。不会自动读取平台账号。';$('import-result').textContent='';$('import-file').value='';$('import-consent').checked=false;$('credential').value='';$('search-query').value='';$('search-collection').value='';$('search-category').value='';$('session-name').textContent='';notice('');$('login-error').textContent=message;void initAuth().then(()=>{if(message)$('login-error').textContent=message;});}
channel.onmessage=()=>lock();
async function api(path,{method='GET',body}={}){
 const c=new AbortController();pending.add(c);try{const r=await fetch('/ui/api'+path,{method,credentials:'same-origin',cache:'no-store',headers:{...(body?{'content-type':'application/json'}:{}),...(method!=='GET'?{'x-csrf-token':session?.csrf??''}:{})},body:body?JSON.stringify(body):undefined,signal:c.signal});const data=await r.json();
 if(r.status===401){lock('登录已过期，请重新输入账号、密码和验证码。');throw new Error('登录已过期');}
 if(!r.ok){const names={strategy_full_policy_required:'维护战略需要本人管理员的完整 L3 权限。',strategy_draft_conflict:'草稿已在其他页面修改，请刷新后核对，不会覆盖。',strategy_publish_conflict:'草稿或正式版已变化，请刷新后重新核对。',strategy_root_required:'发布前请填写总战略总述，并至少新增一个总战略目标。',strategy_owner_dashboard_only:'战略目标只能由本人在网页登录后维护，API Key 和 Agent 无权修改。',strategy_owner_managed:'这个名称保留给本人维护的正式战略，请将建议保存为普通记忆。',memory_conflict:'内容已变化，候选已保留，请在“记忆冲突”处理。',insufficient_scope:'当前授权没有执行此操作的权限。',credential_like_content_rejected:'文件或记录包含疑似凭证，请先在本地脱敏。',rate_limit_exceeded:'请求较多，请稍后重试。',search_index_too_large:'内容过大，请使用本地导入助手分拆。',validation_error:'字段格式不正确，请检查类型、时间和稳定 ID。',payload_too_large:'文件批次过大，请使用本地导入助手。',conflict_version_changed:'当前记录已更新，请刷新后重新选择。',record_policy_denied:'此 Key 的敏感上限或集合权限不允许这项操作。',client_policy_escalation_denied:'新 Key 的权限不能高于当前管理员授权。',retrieval_not_configured:'语义检索尚未配置，请先配置服务端密钥和向量库。',summary_not_configured:'概要模型尚未配置。',model_settings_conflict:'模型设置被其他页面更新，请刷新再保存。',summary_settings_incomplete:'启用概要需要 Base URL、模型和 API Key。',model_key_required:'请输入这个服务的 API Key；更换服务地址后不会复用旧 Key。',model_list_unavailable:'中转站拒绝了模型列表请求，请检查 Key 权限或服务状态。',model_service_unavailable:'云端暂时无法连接模型服务，请稍后重试；已填写的 Key 会保留。',model_request_timeout:'模型列表请求超时，已填写的 Key 会保留，请稍后重试。',invalid_model_response:'中转站返回的模型列表格式无法识别，请检查 API 兼容性。',model_response_too_large:'模型列表响应过大，超过安全读取上限。',invalid_model_endpoint:'Base URL 需要是公开的 HTTPS API 地址，不要包含密钥或查询参数。',evidence_version_changed:'原始证据已更新，请重新选择证据。',summary_evidence_invalid:'模型返回了无效引用，本次概要未保存。',model_provider_rate_limit:'模型供应商临时限流，请稍后重试。'};throw new Error(names[data.error]??'操作失败（'+r.status+'），请检查授权或稍后重试。');}return data;
 }finally{pending.delete(c);}
}
function run(fn){return async(...args)=>{try{await fn(...args);}catch(e){if(e.name!=='AbortError'){if(session&&!$('workspace').hidden){notice(e.message,true);if($('detail').open){let error=$('detail-body').querySelector('.form-error');if(!error){error=el('p','error form-error');error.setAttribute('role','alert');$('detail-body').append(error);}error.textContent=e.message;}}else $('login-error').textContent=e.message;}}};}
function button(text,fn,cls='secondary'){const b=el('button',cls,text);b.type='button';b.addEventListener('click',run(fn));return b;}
function badge(text,sensitive=false){return el('span','badge'+(sensitive?' sensitive':''),text);}
function card(title,subtitle){const c=el('div','card'),h=el('div','card-header');h.append(el('h2','',title));if(subtitle)h.append(el('small','',subtitle));c.append(h);return c;}
function empty(text){return el('div','empty',text);}
function meta(record){const m=el('div','item-meta');m.append(el('span','',platform(record.source_platform)),el('span','',date(record.source_timestamp??record.last_at)));if(record.record_type)m.append(el('span','',types[record.record_type]??record.record_type));return m;}
function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function all(path,key='records'){let cursor='',out=[];do{const d=await api(path+(path.includes('?')?'&':'?')+'limit=50&cursor='+encodeURIComponent(cursor));out.push(...d[key]);cursor=d.next_cursor;}while(cursor!==null&&cursor!=='');return out;}
function modal(title){clearIssuedClientKey();$('detail-title').textContent=title;$('detail-body').replaceChildren();if(!$('detail').open)$('detail').showModal();return $('detail-body');}
function provenance(r){const m=el('div','provenance');for(const [k,v] of Object.entries({'来源平台':platform(r.source_platform),'原发生时间':date(r.source_timestamp),'会话 ID':r.session_id||'—','消息 / 字段 ID':r.source_record_id??r.logical_key??r.id,'版本':r.version??'—','归档范围':r.payload?.data?.completeness??'结构化记忆','保护级别':protectionLabels[r.sensitivity],'来源分类':r.source_kind??'—'}))m.append(el('span','',k),el('span','',String(v)));return m;}
function recordItem(r){const n=el('button','list-item'),h=el('div','item-head');h.append(el('strong','',r.payload.title||r.logical_key||r.payload.text.slice(0,64)),badge(protectionLabels[r.sensitivity]??types[r.record_type],['sensitive','restricted'].includes(r.sensitivity)));n.append(h,meta(r),el('p','item-excerpt',r.payload.text.slice(0,130)));if(r.classification)n.append(el('small','muted',r.classification.categories.map(c=>categoryLabels[c]).join(' · ')));if(r.retrieval)n.append(el('small','',r.retrieval.snippet));n.onclick=run(()=>showRecord(r));return n;}
async function showRecord(r){if(r.truncated)r=await api('/records/'+r.id);const body=modal(r.payload.title||types[r.record_type]);body.append(provenance(r),el('div','record-text',r.payload.text));if(r.citation){const cite=el('div','citation-box');cite.append(el('small','','引用定位'),el('code','',r.id+' · v'+r.version),button('复制引用',async()=>{await navigator.clipboard.writeText(JSON.stringify({...r.citation,document:r.payload.data?.filename,lines:r.payload.data?.line_start?[r.payload.data.line_start,r.payload.data.line_end]:undefined}));notice('引用已复制。');},'quiet'));body.append(cite);}if(r.payload.data){const details=el('details');details.append(el('summary','','结构化数据 / 原始字段'),el('pre','',JSON.stringify(r.payload.data,null,2)));body.append(details);}body.append(classificationEditor(r));const actions=el('div','dialog-actions');actions.append(button('导出这条记录',()=>download(r.id+'.json',r)),button('查看版本历史',async()=>{const history=await api('/records/'+r.id+'/history');if(!session)return;const h=modal('版本历史');for(const v of history.versions){const c=card('版本 '+v.version,date(v.saved_at));c.append(el('div','record-text',v.payload.text));h.append(c);}}));if(r.record_type!=='message'&&can('memory:write'))actions.append(button('编辑记忆',()=>editMemory(r)));body.append(actions);}
function overviewHelpers(){return {el,card,button,date,openCategory:category=>{selectedCategory=category;return navigate('classified');},openSource:async(id,expectedVersion)=>{const record=await api('/records/'+id);await showRecord(record);if(expectedVersion&&record.version!==expectedVersion)notice('原文版本已经变化，请刷新总概览后核对最新出处。',true);}};}
function organizationControls(data,view){
 const controls=el('div','dialog-actions'),start=button(data.enabled?'处理下一批分类与概要':'开始分类并生成总览',async()=>{
  if(!data.enabled)await api('/overview/refresh',{method:'POST',body:{authorized:true,enabled:true,expected_version:data.control_version}});
  const result=await api('/overview/process',{method:'POST',body:{authorized:true}});await navigate(view);notice(result.status==='busy'?'后台正在处理，请稍后查看进度。':'本批分类 '+(result.classified??0)+' 条，纳入概要 '+(result.merged??0)+' 条。已启用的后台任务会继续分批整理。');
 },'primary');start.disabled=!data.configured;controls.append(start);
 if(data.enabled)controls.append(button('暂停自动整理',async()=>{await api('/overview/refresh',{method:'POST',body:{authorized:true,enabled:false,expected_version:data.control_version}});await navigate(view);notice('自动整理已暂停。');}));
 if(!data.configured)controls.append(button('先配置概要模型',()=>navigate('models')));
 controls.append(button('查看分类资料',()=>navigate('classified')));return controls;
}
async function overview(){
 const g=generation,[d,o]=await Promise.all([api('/dashboard'),api('/overview')]);if(g!==generation||!session)return;
 const h=overviewHelpers(),hero=el('div','overview-hero'),intro=el('div');intro.append(el('span','eyebrow','YOUR MEMORY, READY TO CONTINUE'),el('h2','','了解我，也接得上我的工作。'),el('p','','个人情况、开发项目、主线进度和下一步，汇入一份有出处的交接。'));
 const state=el('div','hero-status');state.append(badge('● 私密空间已连接'),el('small','','最近入库'),el('strong','',date(d.totals.last_saved_at)));hero.append(intro,state);if(d.demo)hero.append(el('p','demo-warning','本地示例预览：全部为合成资料，无真实个人信息、真实模型调用或生产数据库访问。'));
 const stats=el('div','stats overview-metrics');for(const [label,value,foot,icon] of [['已记录',d.totals.records,'当前权限可见的全部记录','records'],['今日新增',d.additions.today,'按上海日期和首次入库时间统计','plus'],['个人相关',d.classification.personal,'涉及个人信息与生活的原始资料','personal'],['开发相关',d.classification.development,'涉及开发项目的原始资料','development'],['已分类',d.classification.classified,'主题已明确的原始资料','classified'],['未分类',d.classification.unclassified,'等待整理，不先猜测分类','pending']])stats.append(metric(label,value,foot,icon,h));
 const summary=summaryPanel(o,h);summary.id='primary-overview';summary.append(button('打开详细总概览',()=>navigate('overviewdetail'),'primary'));if(can('admin'))summary.append(organizationControls(o,'overview'));
 const charts=el('div','columns');charts.append(categoryChart(d.classification,h));const sources=card('聊天档案','已导入 '+d.totals.conversations+' 个会话 · '+d.totals.message_records+' 条消息');for(const p of d.platforms){const row=el('div','platform-row'),bar=el('progress');bar.max=Math.max(1,d.totals.message_records);bar.value=p.message_records;row.append(el('span','',platform(p.source_platform)),el('span','',p.conversations+' 个会话 · '+p.message_records+' 条'),bar);sources.append(row);}charts.append(sources);
 const quick=el('div','quick-grid');for(const [view,mark,title,text] of [['classified','◎','按主题找记忆','个人信息、开发项目、其他讨论'],['projects','⌘','查看项目与进度','目标、当前一步、下一步与阻塞'],['overviewdetail','▤','阅读详细总概览','AI 与你看到同一份有出处的概要']]){const item=button('',()=>navigate(view),'quick-card');item.append(el('span','quick-icon',mark),el('strong','',title),el('small','',text),el('span','quick-arrow','↗'));quick.append(item);}
 $('content').replaceChildren(hero,strategyPanel(o.strategy,h,{manage:()=>navigate('strategy')}),stats,charts,summary,quick);
 const lower=el('div','columns'),activity=card('聊天记录按日分布','最近 14 个有消息的日期');for(const day of d.days){const row=el('div','activity-row');row.append(el('span','activity-dot'),el('div','',day.day),el('small','',day.platforms+' 个来源'),el('strong','',day.message_records+' 条'));activity.append(row);}if(!d.days.length)activity.append(empty('对话入库后显示按日足迹。'));lower.append(activity,coverageCard());$('content').append(lower);
 if(d.scope_limited)notice('页面仅统计当前授权可见的资料；私密资料需要对应权限。');
}
async function overviewdetail(){
 const g=generation,o=await api('/overview?detail=full');if(g!==generation||!session)return;const panel=summaryPanel(o,overviewHelpers(),true);if(can('admin')){panel.append(organizationControls(o,'overviewdetail'),button('查看概要版本记录',async()=>{const history=await api('/overview/history'),body=modal('概要版本记录');for(const v of history.versions)body.append(button('查看版本 '+v.revision+' · '+date(v.saved_at),async()=>{const saved=await api('/overview/history?version='+v.revision);body.replaceChildren(summaryPanel(saved,overviewHelpers(),true));}));if(!history.versions.length)body.append(empty('尚无生成版本。'));body.append(el('p','muted','旧版加密保留；当前概要会检查原始来源版本与权限。'));}));}$('content').replaceChildren(strategyPanel(o.strategy,overviewHelpers(),{manage:()=>navigate('strategy')}),panel);
}
async function strategy(){
 const g=generation,data=await api('/strategy');if(g!==generation||!session)return;const h=overviewHelpers(),published=strategyPanel(data.published,h,{full:true});const edit=strategyEditor(data,h,{save:async body=>{await api('/strategy/draft',{method:'POST',body});await navigate('strategy');notice('草稿已保存，Agent 仍读取原正式版本。');},publish:async body=>{await api('/strategy/publish',{method:'POST',body});await navigate('strategy');notice('战略已发布，Agent 下次读取交接时将取得新的正式版本。');}});const history=button('查看战略发布历史',async()=>{const d=await api('/strategy/history'),body=modal('战略发布历史');for(const v of d.versions)body.append(button('查看版本 '+v.version+' · '+date(v.published_at),async()=>{const old=await api('/strategy/history?version='+v.version);body.replaceChildren(el('p','error','这是历史战略，仅供回溯，不代表当前目标。'),strategyPanel({...old,status:'published'},h,{full:true}));}));if(!d.versions.length)body.append(empty('还没有正式发布过目标。'));});$('content').replaceChildren(published,edit,history);
}
async function classified(){
 const g=generation,filters=el('div','filters'),select=el('select');select.setAttribute('aria-label','记忆主题分类');select.append(new Option('全部主题',''));for(const [key,label] of Object.entries(categoryLabels))select.append(new Option(label,key));select.value=selectedCategory;let cursor=0,loadId=0;const list=el('div','list'),more=button('加载更多',()=>load(),'load-more');
 const load=async(reset=false)=>{const ticket=++loadId;if(reset){cursor=0;list.replaceChildren();}selectedCategory=select.value;const d=await api('/records?limit=30&cursor='+cursor+(selectedCategory?'&category='+selectedCategory:''));if(g!==generation||!session||ticket!==loadId)return;for(const r of d.records)list.append(recordItem(r));if(!list.childElementCount)list.append(empty('这一分类目前没有可见资料。未整理的资料请查看“未分类”。'));cursor=d.next_cursor;more.hidden=cursor===null;};select.onchange=run(()=>load(true));filters.append(select,el('p','muted','个人与开发主题可以重叠。分类只描述主题，不自动证明个人事实。'));$('content').replaceChildren(filters,list,more);await load();
}
function classificationEditor(r){
 const box=el('div','classification-editor');if(r.record_type==='summary'&&r.payload.data?.evidence?.length)return el('p','muted','这条是派生概要；请通过出处查看原始资料及其分类。');box.append(el('h3','','主题分类'),el('p','muted',r.classification?'当前：'+r.classification.categories.map(c=>categoryLabels[c]).join(' · ')+' · '+(r.classification.method==='manual'?'手动确认':'AI 根据原文分类'):'这条资料尚未分类。'));
 if(can('memory:write')){const inputs=[];for(const key of ['personal','development','other']){const input=el('input');input.type='checkbox';input.checked=!!r.classification?.categories.includes(key);input.onchange=()=>{if(input.checked){for(const [other,node] of inputs)if(key==='other'||other==='other')node.checked=false;input.checked=true;}};const label=el('label','check');label.append(input,document.createTextNode(categoryLabels[key]));box.append(label);inputs.push([key,input]);}box.append(button('保存主题分类',async()=>{const categories=inputs.filter(([,input])=>input.checked).map(([key])=>key);if(!categories.length)throw new Error('请至少选择一个主题。');await api('/classifications',{method:'POST',body:{authorized:true,id:r.id,version:r.version,expected_revision:r.classification?.revision??0,categories}});await showRecord(await api('/records/'+r.id));notice('分类已保存；原始记录保持可回溯。');}));}return box;
}
function coverageCard(){const c=card('每日同步','从 2026.10.11 开始'),items=el('div','coverage');for(const [name,status] of [['执行时间','每天 23:50'],['本机 Codex','本地文本自动归档'],['可读 ChatGPT / 云端聊天','应用接口增量读取'],['Antigravity / Claude 网页版','客户端提交或文件导入']]){const n=el('div');n.append(el('span','',name),el('small','',status));items.append(n);}c.append(items,el('div','coverage-note','定时任务依赖本机和桌面应用运行。MCP 接通不等于私有历史自动采集；遗漏会在后续执行补传。'));return c;}
