 file.onchange=run(async()=>{records=null;records=await prepare();if(records)preview.textContent=file.files[0].name+' · '+records.length+' 个原文片段 · 默认私密；重复文件会自动去重。';});
 const consent=el('input');consent.type='checkbox';consent.required=true;const permission=el('label','check');permission.append(consent,document.createTextNode('我授权将这份资料保存到自己的记忆中心'));const submit=el('button','primary','确认保存资料'),progress=el('p','muted');progress.setAttribute('role','status');submit.type='submit';form.append(permission,submit,progress);body.append(form);
