  e.preventDefault();const scopes=checks.filter(x=>x[1].checked).map(x=>x[0]),policy={read_level:Number(readLevel.value),write_level:Number(writeLevel.value),collections:selectedCollections.filter(x=>x[1].checked).map(x=>x[0])};
